export class DashboardDurableObject {
  constructor(state, env) { this.state=state; this.sessions=new Set(); }
  async fetch(request) { const url=new URL(request.url); if(url.pathname==='/ws'){if(request.headers.get('Upgrade')!=='websocket')return new Response('Expected WebSocket',{status:426});const pair=new WebSocketPair(),client=pair[0],server=pair[1];server.accept();this.sessions.add(server);server.send(JSON.stringify({type:'init',data:await this.getData()}));server.addEventListener('message',async e=>{try{const m=JSON.parse(e.data);if(m.type==='update'){await this.state.storage.put('dashboardData',m.data);this.broadcast({type:'update',data:m.data},server)}}catch(err){server.send(JSON.stringify({type:'error',message:String(err)}))}});server.addEventListener('close',()=>this.sessions.delete(server));server.addEventListener('error',()=>this.sessions.delete(server));return new Response(null,{status:101,webSocket:client})} if(url.pathname==='/api/data'){if(request.method==='GET')return Response.json(await this.getData());if(request.method==='POST'){const body=await request.json();await this.state.storage.put('dashboardData',body);this.broadcast({type:'update',data:body});return Response.json({ok:true})}} return new Response('Not found',{status:404}); }
  async getData(){const def={appVersion:'12.4.0',companyName:'บริษัท สายไฟฟ้าบางกอกเคเบิ้ล จำกัด',currentDepartmentId:'bcc2-insulation-packing',departments:[{id:'bcc2-insulation-packing',name:'ฝ่ายหุ้มฉนวนและบรรจุสาย BCC2',targetDays:'2937',monthRecords:{},manualOverrides:{},data:{}}]};const saved=await this.state.storage.get('dashboardData');if(!saved)return def;if(!Array.isArray(saved.departments))return {...def,currentDepartmentId:'default-department',departments:[{id:'default-department',name:saved.departmentName||'ฝ่ายเริ่มต้น',targetDays:saved.targetDays||'2937',monthRecords:{},manualOverrides:{},data:{}}]};return {...def,...saved}}
  broadcast(message,exceptSocket=null){const payload=JSON.stringify(message);for(const s of this.sessions){if(s!==exceptSocket){try{s.send(payload)}catch{this.sessions.delete(s)}}}}
}
const html="<!doctype html><html lang=\"th\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>BCC Safety Web Application</title>\n<style>\n@import url('https://fonts.googleapis.com/css2?family=Sarabun:wght@300;400;600;700;800&display=swap');\n*{box-sizing:border-box}body{margin:0;font-family:'TH Sarabun New','Sarabun',Tahoma,sans-serif;background:#02112c;color:#eaffff}.hidden{display:none!important}.app{min-height:100vh;background:#071a3a;border:6px solid #062b6f;padding:8px 8px 14px}.login{position:fixed;inset:0;background:#0c316e;display:grid;place-items:center;z-index:99}.login-card{width:min(420px,92vw);background:#f6f8fb;color:#073068;border-radius:12px;padding:28px;border:3px solid #29a7ff;box-shadow:0 20px 60px #0008}.login-card h1{margin:0 0 18px;font-size:32px;color:#064b92}.login-card p{font-size:18px}.login-card input{width:100%;font-family:inherit;font-size:20px;padding:14px;margin:8px 0;border:1px solid #79aee5;border-radius:8px}.login-card button{width:100%;font-family:inherit;font-size:20px;font-weight:900;padding:14px;border:0;border-radius:8px;background:#075aa8;color:white;margin-top:18px;cursor:pointer}.login-error{color:#b00020;font-size:18px;font-weight:900;min-height:28px;margin-top:8px}\n.header{position:relative;height:128px;display:grid;grid-template-columns:230px 1fr 128px;gap:14px;align-items:center;border:3px solid #1586df;border-radius:8px;padding:10px 16px;color:#fff;overflow:hidden;background-image:url('data:image/jpeg;base64,');background-size:cover;background-position:center;background-repeat:no-repeat}.header:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.50),rgba(0,20,70,.20),rgba(0,0,0,.50));z-index:0}.header>*{position:relative;z-index:1}.bcc-logo{width:210px;height:96px;object-fit:contain;display:block}.safety-logo{width:104px;height:104px;object-fit:contain;display:block;justify-self:end}.brand-title{text-align:center;line-height:1.1;text-shadow:0 3px 8px #000}.company-line,.department-line{width:100%;border:0;background:transparent;text-align:center;font-family:inherit;color:#fff;font-weight:900;text-shadow:0 3px 8px #000}.company-line{font-size:56px}.department-line{font-size:40px;margin-top:4px}.toolbar{margin-top:10px;padding:12px 14px;background:#04142e;color:#fff;display:grid;grid-template-columns:1fr 1.2fr auto;gap:12px;align-items:center;border-radius:10px;border:2px solid #0b75c9;font-size:25px}.toolbar select,.toolbar input,.datebar select{font-family:inherit;font-size:24px;padding:6px 10px;border-radius:6px;border:2px solid #5eb4ff}.toolbar button,.panel button{font-family:inherit;font-size:23px;font-weight:900;border:0;border-radius:6px;padding:8px 12px;cursor:pointer;color:white}.btn-add{background:#009a72}.btn-del{background:#bd1733}.btn-clear{background:#39475c}.btn-export{background:#0b58b5}.sync{font-weight:900;color:#ffeb3b}.hint{font-size:20px;color:#d7f7ff}.datebar{margin-top:10px;background:#062d6d;border:2px solid #208fe4;border-radius:10px;padding:10px 14px;display:grid;grid-template-columns:1fr 1fr;gap:12px;align-items:center;font-size:25px}.date-group{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.month-label-big{font-size:34px;font-weight:900;color:#fff;text-shadow:0 2px 5px #000}.date-note{grid-column:1/-1;color:#d7f7ff;font-size:20px}.main{display:grid;grid-template-columns:60% 40%;min-height:640px;background:#edf6ff;color:#062047;border-radius:12px;margin-top:10px;overflow:hidden}.left{padding:18px 22px 10px 10px;border-right:6px solid #0b75c9}.right{padding:18px 10px 10px 22px}.head{text-align:center;color:#123d9a;font-size:56px;font-weight:900;line-height:1.05;margin-bottom:18px}.row{display:grid;grid-template-columns:1fr 380px;gap:18px;align-items:center;margin-bottom:16px}.th{font-size:34px;font-weight:800;line-height:1.05}.en{font-size:27px;font-weight:900;line-height:1.05}.green{color:#005b4a}.red{color:#8e102c}.val{display:flex;justify-content:flex-end;gap:6px;align-items:center}.date,.month,.year,.num,.monthbox input{font-family:inherit;border:3px solid #7894b4;background:#f7fbff;font-weight:900;color:#071b3d;text-align:center;padding:6px;border-radius:3px;box-shadow:inset 0 0 5px #0004}.date{width:92px;font-size:48px}.month{width:155px;font-size:30px}.year{width:135px;font-size:48px}.num{width:230px;font-size:58px}.num[readonly],.date[readonly],.month[readonly],.year[readonly]{background:#e7eef7}.rhead{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:12px;align-items:start}.monthbox{display:grid;gap:10px;width:260px}.monthbox input{width:100%;font-size:30px;background:#f8f4fb;color:#243a80}.cal{margin-top:16px;display:grid;grid-template-columns:repeat(7,1fr);gap:7px}.day{min-height:48px;border:2px solid #8aa7c7;background:#f2f6fb;color:#24354f;font-size:32px;font-weight:900;cursor:pointer;display:grid;place-items:center}.day.blank{opacity:.25;cursor:default}.day.future{background:#f2f6fb;color:#9aa7b6;cursor:default}.status-green{background:#006b58!important;color:white!important}.status-yellow{background:#d69a00!important;color:#111!important}.status-red{background:#9c1131!important;color:white!important}.auto-green{background:#006b58;color:white;box-shadow:inset 0 0 0 3px #70dbc8}.legend{margin-top:20px;font-size:22px;line-height:1.05}.legend-row{display:grid;grid-template-columns:34px 1fr;gap:12px;align-items:center;margin-bottom:12px}.box{width:32px;height:32px}.panel{margin-top:16px;padding:12px;background:#ffffffcc;border:2px dashed #0b75c9;border-radius:8px;display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.footer{margin-top:12px;border-radius:14px;overflow:hidden;border:3px solid #208fe4;background:#ffffffd9;color:#062047}.footer-main{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:12px;align-items:center;padding:12px 18px;background:linear-gradient(90deg,#020735,#063b97,#0077ff);color:white}.footer-brand{font-size:30px;font-weight:900}.footer-brand small{display:block;font-size:19px;color:#d9fff5}.footer-maker{font-size:28px;font-weight:900;text-align:center}.footer-maker span{display:block;font-size:22px;color:#eafff8}.footer-meta{text-align:right;font-size:21px}.export-sheet{position:absolute;left:-99999px;top:0;width:900px;background:#edf6ff;color:#062047;font-family:'TH Sarabun New','Sarabun',Tahoma,sans-serif;border:8px solid #062d6d;padding:18px}.ex-title{background:linear-gradient(90deg,#020735,#063b97,#0077ff);color:white;border-radius:12px;padding:18px;text-align:center;font-size:42px;font-weight:900}.ex-logo{max-width:220px;display:block;margin:0 auto 10px}.ex-sub{font-size:26px;color:#d7f7ff}.ex-section{margin-top:18px;border:3px solid #0b75c9;border-radius:12px;background:white;overflow:hidden}.ex-section h2{margin:0;background:#062d6d;color:white;padding:10px 16px;font-size:34px}.ex-body{padding:14px 16px;font-size:28px}.ex-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.ex-card{border:2px solid #8aa7c7;border-radius:10px;padding:10px;background:#f5faff}.ex-label{font-size:24px;color:#36506f}.ex-value{font-size:42px;font-weight:900;color:#061a3b}.ex-calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}.ex-day{height:54px;border:2px solid #8aa7c7;display:grid;place-items:center;font-size:30px;font-weight:900;background:#f2f6fb}.ex-footer{margin-top:18px;text-align:center;font-size:24px;background:#04142e;color:white;border-radius:10px;padding:12px}@media(max-width:1100px){.header,.main,.row,.rhead,.toolbar,.footer-main,.datebar{grid-template-columns:1fr}.header{height:auto;text-align:center}.bcc-logo,.safety-logo{margin:auto;justify-self:center}.left{border-right:0;border-bottom:6px solid #0b75c9}.val{justify-content:flex-start;flex-wrap:wrap}.panel{grid-template-columns:1fr}.footer-meta,.footer-maker{text-align:left}.monthbox{width:100%}}\n</style></head><body>\n<div id=\"login\" class=\"login\"><div class=\"login-card\"><h1>BCC Safety Login</h1><p>เข้าสู่ระบบ Web Application</p><input id=\"loginUser\" autocomplete=\"username\" placeholder=\"User\"><input id=\"loginPass\" autocomplete=\"current-password\" type=\"password\" placeholder=\"Password\"><div id=\"loginError\" class=\"login-error\"></div><button type=\"button\" id=\"loginBtn\" onclick=\"doLogin()\">Login</button></div></div>\n<div id=\"app\" class=\"app hidden\"><div class=\"header\"><img class=\"bcc-logo\" src=\"data:image/png;base64,\" alt=\"BCC\"><div class=\"brand-title\"><input id=\"companyName\" class=\"company-line\" value=\"บริษัท สายไฟฟ้าบางกอกเคเบิ้ล จำกัด\"><input id=\"departmentTitle\" class=\"department-line\" readonly></div><img class=\"safety-logo\" src=\"data:image/png;base64,\" alt=\"Safety First\"></div>\n<div class=\"toolbar\"><div>เวลา Real-time: <span id=\"clock\">-</span><br><span class=\"hint\">สถานะ Sync: <span id=\"sync\" class=\"sync\">กำลังเชื่อมต่อ</span></span></div><div>ดูข้อมูลแยกตามฝ่าย: <select id=\"departmentSelect\"></select> <input id=\"newDepartmentName\" placeholder=\"พิมพ์ชื่อฝ่ายใหม่\"></div><div><button class=\"btn-add\" onclick=\"addDepartment()\">+ เพิ่มฝ่าย</button><button class=\"btn-del\" onclick=\"deleteDepartment()\">ลบฝ่าย</button><button class=\"btn-clear\" onclick=\"logout()\">Logout</button></div></div>\n<div class=\"datebar\"><div class=\"date-group\">วันที่คำนวณ Safety Record: <select id=\"selectDay\"></select><select id=\"selectMonth\"></select><select id=\"selectYear\"></select></div><div class=\"date-group\"><span class=\"month-label-big\">เดือนที่แสดง Accident Record:</span> <select id=\"accMonth\"></select><select id=\"accYear\"></select></div><div class=\"date-note\">Auto Update สีเขียว = วันทำงานที่ไม่เกิดอุบัติเหตุ ตั้งแต่ 1/1/2566 ถึงวันที่ปัจจุบัน | วันอนาคต = ว่าง</div></div>\n<div class=\"main\"><div class=\"left\"><div class=\"head\">สถิติความปลอดภัย<br>SAFETY RECORD</div><div class=\"row\"><div><div class=\"th\">วันที่บันทึก</div><div class=\"en\">RECORD DATE</div></div><div class=\"val\"><input id=\"recordDay\" class=\"date\" readonly><input id=\"recordMonthTH\" class=\"month\" readonly><input id=\"recordYear\" class=\"year\" readonly></div></div><div class=\"row\"><div><div class=\"th green\">ทำงานมาแล้วโดยไม่เกิดอุบัติเหตุถึงขั้นหยุดงาน (วัน)</div><div class=\"en green\">OPERATED WITHOUT A LOST TIME ACCIDENT (DAYS)</div></div><div class=\"val\"><input id=\"operateDays\" class=\"num\" type=\"number\"></div></div><div class=\"row\"><div><div class=\"th green\">เป้าหมาย (วัน)</div><div class=\"en green\">TARGET (DAYS)</div></div><div class=\"val\"><input id=\"targetDays\" class=\"num\" type=\"number\"></div></div><div class=\"row\"><div><div class=\"th red\">เกิดอุบัติเหตุถึงขั้นหยุดงานครั้งสุดท้ายเมื่อ</div><div class=\"en red\">LAST ACCIDENT OCCURRED</div></div><div class=\"val\"><input id=\"lastAccidentDay\" class=\"date\" readonly><input id=\"lastAccidentMonthTH\" class=\"month\" readonly><input id=\"lastAccidentYear\" class=\"year\" readonly></div></div><div class=\"row\"><div><div class=\"th green\">สถิติที่ดีที่สุดที่ไม่เกิดอุบัติเหตุถึงขั้นหยุดงาน (วัน)</div><div class=\"en green\">THE BEST RECORD (DAYS)</div></div><div class=\"val\"><input id=\"bestRecord\" class=\"num\" type=\"number\"></div></div><div class=\"panel\"><button class=\"btn-export\" onclick=\"exportImage()\">Export รูปแนวตั้ง</button><button class=\"btn-export\" onclick=\"exportLandscape()\">Export รูปแนวนอน</button></div></div><div class=\"right\"><div class=\"rhead\"><div class=\"head\" style=\"text-align:left;margin-bottom:8px;font-size:40px\">สถิติความปลอดภัยประจำเดือน<br>ACCIDENT RECORD FOR</div><div class=\"monthbox\"><input id=\"displayMonthTH\" readonly><input id=\"displayMonthEN\" readonly></div></div><div id=\"cal\" class=\"cal\"></div><div class=\"legend\"><div class=\"legend-row\"><div class=\"box status-green\"></div><div>วันทำงานที่ไม่เกิดอุบัติเหตุ<br>REGULAR WORKING DAY WITH NO LOST TIME ACCIDENT</div></div><div class=\"legend-row\"><div class=\"box status-yellow\"></div><div>วันที่เกิดอุบัติเหตุแต่ไม่ถึงขั้นหยุดงาน<br>ACCIDENT OCCURRED WITH NO LOST TIME</div></div><div class=\"legend-row\"><div class=\"box status-red\"></div><div>วันที่เกิดอุบัติเหตุถึงขั้นหยุดงาน<br>LOST TIME ACCIDENT</div></div></div></div></div><footer class=\"footer\"><div class=\"footer-main\"><div class=\"footer-brand\">BCC Safety Web Application<small>Interactive Safety Record Dashboard</small></div><div class=\"footer-maker\">created by siriphan meesombut<span>ID4.0 teams</span></div><div class=\"footer-meta\">Version 12.4<br>Login Fixed<br>Manual Number Edit</div></div></footer></div>\n<script src=\"https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js\"></script><script>\nconst LOGIN_USER='BCC';const LOGIN_PASSWORDS=['Siriphan.m','siriphan.m','Siriphan.M'];const monthsTH=['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];const monthsEN=['JANUARY','FEBRUARY','MARCH','APRIL','MAY','JUNE','JULY','AUGUST','SEPTEMBER','OCTOBER','NOVEMBER','DECEMBER'];let appData={appVersion:'12.4.0',companyName:'บริษัท สายไฟฟ้าบางกอกเคเบิ้ล จำกัด',currentDepartmentId:'bcc2-insulation-packing',departments:[{id:'bcc2-insulation-packing',name:'ฝ่ายหุ้มฉนวนและบรรจุสาย BCC2',targetDays:'2937',monthRecords:{},manualOverrides:{},data:{}}]};let ws,timer;\nfunction doLogin(){const user=(document.getElementById('loginUser')?.value||'').trim();const pass=(document.getElementById('loginPass')?.value||'').trim();const err=document.getElementById('loginError'),loginEl=document.getElementById('login'),appEl=document.getElementById('app');if(user===LOGIN_USER&&LOGIN_PASSWORDS.includes(pass)){sessionStorage.setItem('bcc_login','1');if(loginEl)loginEl.classList.add('hidden');if(appEl)appEl.classList.remove('hidden');if(err)err.textContent='';if(typeof apply==='function')apply();if(typeof connect==='function')connect();}else{if(err)err.textContent='User หรือ Password ไม่ถูกต้อง: ใช้ BCC / Siriphan.m';}}\nfunction logout(){sessionStorage.removeItem('bcc_login');location.reload()}function initAuth(){const loginEl=document.getElementById('login'),appEl=document.getElementById('app');if(sessionStorage.getItem('bcc_login')==='1'){if(loginEl)loginEl.classList.add('hidden');if(appEl)appEl.classList.remove('hidden');if(typeof apply==='function')apply();if(typeof connect==='function')connect();}}\nfunction uid(){return 'dep-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7)}function todayTH(){const n=new Date();return{d:n.getDate(),m:n.getMonth()+1,y:n.getFullYear()+543}}function ceY(be){return Number(be)-543}function dateObj(be,m,d){return new Date(ceY(be),m-1,d)}function daysInMonth(be,m){return new Date(ceY(be),m,0).getDate()}function dateDiff(a,b){return Math.floor((b-a)/86400000)}function startAuto(){return dateObj(2566,1,1)}function todayDate(){const t=todayTH();return dateObj(t.y,t.m,t.d)}function isFuture(y,m,d){return dateObj(Number(y),Number(m),Number(d))>todayDate()}function isAutoGreen(y,m,d){const dt=dateObj(y,m,d);return dt>=startAuto()&&dt<=todayDate()}function key(y,m){return y+'-'+String(m).padStart(2,'0')}function currentDep(){return appData.departments.find(d=>d.id===appData.currentDepartmentId)||appData.departments[0]}function normalize(){if(!Array.isArray(appData.departments)||!appData.departments.length)appData.departments=[{id:uid(),name:'ฝ่ายเริ่มต้น',targetDays:'2937',monthRecords:{},manualOverrides:{},data:{}}];if(!appData.currentDepartmentId)appData.currentDepartmentId=appData.departments[0].id;appData.departments.forEach(d=>{d.targetDays=d.targetDays||'2937';d.monthRecords=d.monthRecords||{};d.manualOverrides=d.manualOverrides||{};d.data=d.data||{}})}function setStatus(x){const el=document.getElementById('sync');if(el)el.textContent=x}function fillYearSelect(sel){sel.innerHTML='';for(let y=2566;y<=2575;y++){let o=document.createElement('option');o.value=y;o.textContent=y;sel.appendChild(o)}}function fillMonthSelect(sel){sel.innerHTML='';monthsTH.forEach((m,i)=>{let o=document.createElement('option');o.value=i+1;o.textContent=m;sel.appendChild(o)})}function fillDays(prefer){const max=daysInMonth(selectYear.value,selectMonth.value);selectDay.innerHTML='';for(let d=1;d<=max;d++){let o=document.createElement('option');o.value=d;o.textContent=d;selectDay.appendChild(o)}selectDay.value=Math.min(prefer||1,max)}function initDateSelectors(){fillYearSelect(selectYear);fillMonthSelect(selectMonth);fillYearSelect(accYear);fillMonthSelect(accMonth);const t=todayTH();selectYear.value=t.y;selectMonth.value=t.m;fillDays(t.d);accYear.value=t.y;accMonth.value=t.m}function renderDepartments(){normalize();departmentSelect.innerHTML='';appData.departments.forEach(d=>{const o=document.createElement('option');o.value=d.id;o.textContent=d.name;departmentSelect.appendChild(o)});departmentSelect.value=appData.currentDepartmentId;departmentTitle.value=currentDep().name;companyName.value=appData.companyName||companyName.value}function monthRecord(dep,y=accYear.value,m=accMonth.value){const k=key(y,m);dep.monthRecords[k]=dep.monthRecords[k]||{};return dep.monthRecords[k]}function effectiveStatus(dep,y,m,d){if(isFuture(y,m,d))return '';const rec=dep.monthRecords[key(y,m)]||{};return rec[d]||(isAutoGreen(Number(y),Number(m),Number(d))?'green':'')}function computeStats(dep){const y=Number(selectYear.value),m=Number(selectMonth.value),d=Number(selectDay.value),selected=dateObj(y,m,d);let lastRed=null,best=0,streak=0;for(let yy=2566;yy<=y;yy++){for(let mm=1;mm<=12;mm++){if(yy===y&&mm>m)break;const max=daysInMonth(yy,mm);for(let dd=1;dd<=max;dd++){const dt=dateObj(yy,mm,dd);if(dt>selected||dt>todayDate())break;const st=effectiveStatus(dep,yy,mm,dd);if(st==='red'){if(streak>best)best=streak;streak=0;lastRed={y:yy,m:mm,d:dd,date:dt}}else if(dt>=startAuto())streak++}}}if(streak>best)best=streak;const end=selected>todayDate()?todayDate():selected;const operate=lastRed?Math.max(0,dateDiff(lastRed.date,end)):dateDiff(startAuto(),end)+1;return{operate:Math.max(0,operate),best,lastRed}}\nfunction apply(){normalize();renderDepartments();const dep=currentDep();recordDay.value=selectDay.value;recordMonthTH.value=monthsTH[selectMonth.value-1];recordYear.value=selectYear.value;displayMonthTH.value=monthsTH[accMonth.value-1];displayMonthEN.value=monthsEN[accMonth.value-1];const s=computeStats(dep);operateDays.value=(dep.manualOverrides.operateDays!==undefined&&dep.manualOverrides.operateDays!=='')?dep.manualOverrides.operateDays:s.operate;bestRecord.value=(dep.manualOverrides.bestRecord!==undefined&&dep.manualOverrides.bestRecord!=='')?dep.manualOverrides.bestRecord:s.best;if(s.lastRed){lastAccidentDay.value=s.lastRed.d;lastAccidentMonthTH.value=monthsTH[s.lastRed.m-1];lastAccidentYear.value=s.lastRed.y}else{lastAccidentDay.value='-';lastAccidentMonthTH.value='-';lastAccidentYear.value='-'}targetDays.value=dep.targetDays||'2937';drawCalendar()}function collect(){appData.companyName=companyName.value;const dep=currentDep();dep.targetDays=targetDays.value;dep.manualOverrides=dep.manualOverrides||{};dep.manualOverrides.operateDays=operateDays.value;dep.manualOverrides.bestRecord=bestRecord.value}function send(){collect();if(ws&&ws.readyState===1){ws.send(JSON.stringify({type:'update',data:appData}));setStatus('บันทึกและ Sync แล้ว')}else fetch('/api/data',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(appData)}).then(()=>setStatus('บันทึกผ่าน API แล้ว'))}function autoSave(){clearTimeout(timer);timer=setTimeout(()=>{send();apply()},180)}function drawCalendar(){const dep=currentDep(),rec=monthRecord(dep),max=daysInMonth(accYear.value,accMonth.value);cal.innerHTML='';for(let i=1;i<=31;i++){const c=document.createElement('div');if(i>max){c.className='day blank';cal.appendChild(c);continue}if(isFuture(accYear.value,accMonth.value,i)){c.className='day future';c.textContent=i;cal.appendChild(c);continue}const stored=rec[i]||'',eff=stored||(isAutoGreen(Number(accYear.value),Number(accMonth.value),i)?'green':'');c.className='day'+(stored?' status-'+stored:(eff==='green'?' auto-green':''));c.textContent=i;c.onclick=()=>toggleDay(i);cal.appendChild(c)}}function toggleDay(i){if(isFuture(accYear.value,accMonth.value,i))return;const rec=monthRecord(currentDep()),cur=rec[i]||'',auto=isAutoGreen(Number(accYear.value),Number(accMonth.value),i);if(!cur)rec[i]=auto?'yellow':'green';else if(cur==='green')rec[i]='yellow';else if(cur==='yellow')rec[i]='red';else delete rec[i];apply();send()}function addDepartment(){const name=newDepartmentName.value.trim();if(!name){alert('กรุณาพิมพ์ชื่อฝ่าย');return}const d={id:uid(),name,targetDays:'2937',monthRecords:{},manualOverrides:{},data:{}};appData.departments.push(d);appData.currentDepartmentId=d.id;newDepartmentName.value='';apply();send()}function deleteDepartment(){if(appData.departments.length<=1){alert('ต้องมีอย่างน้อย 1 ฝ่าย');return}const dep=currentDep();if(!confirm('ต้องการลบ '+dep.name+' หรือไม่?'))return;appData.departments=appData.departments.filter(x=>x.id!==dep.id);appData.currentDepartmentId=appData.departments[0].id;apply();send()}function exportCalendarHtml(){const dep=currentDep(),max=daysInMonth(accYear.value,accMonth.value);let out='';for(let i=1;i<=31;i++){if(i>max){out+='<div class=\"ex-day\"></div>';continue}const st=effectiveStatus(dep,accYear.value,accMonth.value,i);out+='<div class=\"ex-day '+(st?'status-'+st:'')+'\">'+i+'</div>'}return out}function buildPortrait(){const dep=currentDep(),st=computeStats(dep),dateText=selectDay.value+' '+monthsTH[selectMonth.value-1]+' '+selectYear.value,last=st.lastRed?st.lastRed.d+' '+monthsTH[st.lastRed.m-1]+' '+st.lastRed.y:'-',div=document.createElement('div');div.className='export-sheet';div.innerHTML='<div class=\"ex-title\"><img class=\"ex-logo\" src=\"data:image/png;base64,\">BCC Safety Record Web Application<div class=\"ex-sub\">ข้อมูลฝ่าย > สถิติความปลอดภัย > สถิติความปลอดภัยประจำเดือน</div></div><section class=\"ex-section\"><h2>1) ข้อมูลฝ่าย</h2><div class=\"ex-body\"><div class=\"ex-grid\"><div class=\"ex-card\"><div class=\"ex-label\">บริษัท</div><div class=\"ex-value\" style=\"font-size:30px\">'+companyName.value+'</div></div><div class=\"ex-card\"><div class=\"ex-label\">ฝ่าย</div><div class=\"ex-value\" style=\"font-size:30px\">'+dep.name+'</div></div><div class=\"ex-card\"><div class=\"ex-label\">วันที่คำนวณ</div><div class=\"ex-value\" style=\"font-size:34px\">'+dateText+'</div></div><div class=\"ex-card\"><div class=\"ex-label\">เดือนที่แสดง</div><div class=\"ex-value\" style=\"font-size:34px\">'+monthsTH[accMonth.value-1]+' / '+monthsEN[accMonth.value-1]+' '+accYear.value+'</div></div></div></div></section><section class=\"ex-section\"><h2>2) สถิติความปลอดภัย</h2><div class=\"ex-body\"><div class=\"ex-grid\"><div class=\"ex-card\"><div class=\"ex-label\">OPERATED WITHOUT LOST TIME ACCIDENT</div><div class=\"ex-value\">'+operateDays.value+' วัน</div></div><div class=\"ex-card\"><div class=\"ex-label\">TARGET</div><div class=\"ex-value\">'+targetDays.value+' วัน</div></div><div class=\"ex-card\"><div class=\"ex-label\">LAST ACCIDENT OCCURRED</div><div class=\"ex-value\" style=\"font-size:34px\">'+last+'</div></div><div class=\"ex-card\"><div class=\"ex-label\">THE BEST RECORD</div><div class=\"ex-value\">'+bestRecord.value+' วัน</div></div></div></div></section><section class=\"ex-section\"><h2>3) สถิติความปลอดภัยประจำเดือน</h2><div class=\"ex-body\"><div style=\"font-size:30px;font-weight:900;margin-bottom:8px\">ACCIDENT RECORD FOR '+monthsTH[accMonth.value-1]+' / '+monthsEN[accMonth.value-1]+' '+accYear.value+'</div><div class=\"ex-calendar\">'+exportCalendarHtml()+'</div></div></section><div class=\"ex-footer\">created by siriphan meesombut ID4.0 teams | BCC Safety Web Application v12.4</div>';return div}async function exportImage(){collect();const dep=currentDep(),safe=(dep.name||'department').replace(/[\\\\/:*?\"<>|\\s]+/g,'-').slice(0,60),sheet=buildPortrait();document.body.appendChild(sheet);try{const canvas=await html2canvas(sheet,{backgroundColor:'#edf6ff',scale:2,useCORS:true,logging:false});const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='bcc-safety-portrait-'+safe+'-'+accYear.value+'-'+accMonth.value+'.png';a.click();setStatus('Export รูปแนวตั้งสำเร็จ')}catch(e){alert('Export รูปไม่สำเร็จ: '+e.message)}finally{sheet.remove()}}async function exportLandscape(){collect();const dep=currentDep(),safe=(dep.name||'department').replace(/[\\\\/:*?\"<>|\\s]+/g,'-').slice(0,60);setStatus('กำลัง Export รูปแนวนอน PNG');try{const canvas=await html2canvas(app,{backgroundColor:'#071a3a',scale:2,useCORS:true,logging:false,windowWidth:app.scrollWidth,windowHeight:app.scrollHeight});const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='bcc-safety-landscape-'+safe+'-'+accYear.value+'-'+accMonth.value+'.png';a.click();setStatus('Export รูปแนวนอนสำเร็จ')}catch(e){alert('Export รูปแนวนอนไม่สำเร็จ: '+e.message);setStatus('Export รูปแนวนอนไม่สำเร็จ')}}const clockEl=document.getElementById('clock');function clock(){clockEl.textContent=new Date().toLocaleString('th-TH',{dateStyle:'full',timeStyle:'medium'})}function connect(){const p=location.protocol==='https:'?'wss':'ws';ws=new WebSocket(p+'://'+location.host+'/ws');ws.onopen=()=>setStatus('เชื่อมต่อ Real-time แล้ว');ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.type==='init'||m.type==='update'){appData=m.data;apply();setStatus(m.type==='init'?'โหลดข้อมูลสำเร็จ':'รับข้อมูล Real-time แล้ว')}};ws.onclose=()=>{setStatus('หลุดการเชื่อมต่อ กำลังลองใหม่');setTimeout(connect,2000)}}function bind(){companyName.addEventListener('input',autoSave);targetDays.addEventListener('input',autoSave);operateDays.addEventListener('input',autoSave);bestRecord.addEventListener('input',autoSave);departmentSelect.addEventListener('change',e=>{collect();appData.currentDepartmentId=e.target.value;apply();send()});selectYear.addEventListener('change',()=>{fillDays(selectDay.value);apply();send()});selectMonth.addEventListener('change',()=>{fillDays(selectDay.value);apply();send()});selectDay.addEventListener('change',()=>{apply();send()});accYear.addEventListener('change',()=>{apply();send()});accMonth.addEventListener('change',()=>{apply();send()});['loginUser','loginPass'].forEach(id=>{const el=document.getElementById(id);if(el)el.addEventListener('keydown',e=>{if(e.key==='Enter')doLogin()})})}\ninitDateSelectors();bind();apply();clock();setInterval(clock,1000);initAuth();\n</script></body></html>";
